def store_data(key, value, ttl=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0180000" if __import__("os").path.isdir("./environment_mix/0180000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now.isoformat() + "Z"

    entries = _load("cache_entries.json")
    ops = _load("cache_operations.json")
    snaps = _load("cache_stats_snapshots.json")
    policies = _load("cache_retention_policies.json")

    op_row = {
        "id": "op_" + uuid.uuid4().hex,
        "op_type": "store_data",
        "cache_entry_id": None,
        "cache_key": key if isinstance(key, str) else None,
        "ttl_seconds": ttl if isinstance(ttl, (int, float)) and not isinstance(ttl, bool) else None,
        "result": "error",
        "error_code": None,
        "duration_ms": None,
        "created_at": now_iso,
        "updated_at": now_iso,
    }

    def _finalize_and_return(payload, result, error_code=None):
        op_row["result"] = result
        op_row["error_code"] = error_code
        op_row["duration_ms"] = max(0, int(round((time.time() - t0) * 1000)))
        op_row["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        ops.append(op_row)
        _save("cache_operations.json", ops)
        return payload

    # Validation
    if not isinstance(key, str) or key.strip() == "":
        return _finalize_and_return(_err("VALIDATION_ERROR", "key must be a non-empty string"), "error", "VALIDATION_ERROR")
    if ttl is not None:
        if not isinstance(ttl, (int, float)) or isinstance(ttl, bool):
            return _finalize_and_return(_err("VALIDATION_ERROR", "ttl must be a positive number when provided"), "error", "VALIDATION_ERROR")
        if ttl <= 0:
            return _finalize_and_return(_err("VALIDATION_ERROR", "ttl must be > 0 when provided"), "error", "VALIDATION_ERROR")

    # Compute value_bytes as UTF-8 JSON length (approx)
    try:
        value_bytes = len(json.dumps(value, ensure_ascii=False, separators=(",", ":")).encode("utf-8"))
    except (TypeError, ValueError):
        return _finalize_and_return(_err("VALIDATION_ERROR", "value must be JSON-serializable"), "error", "VALIDATION_ERROR")
    if value_bytes < 0:
        return _finalize_and_return(_err("VALIDATION_ERROR", "value_bytes must be >= 0"), "error", "VALIDATION_ERROR")

    # Find active policy (at most one)
    active_policy = None
    for p in policies:
        if p.get("status") == "active":
            active_policy = p
            break

    # Quota enforcement
    if active_policy is not None:
        max_entry_bytes = active_policy.get("max_entry_bytes")
        max_total_bytes = active_policy.get("max_total_bytes")
        max_keys = active_policy.get("max_keys")

        if max_entry_bytes is not None:
            if not isinstance(max_entry_bytes, int) or max_entry_bytes <= 0:
                # Bad policy row; treat as service error -> QUOTA_EXCEEDED is closest per tool description
                return _finalize_and_return(_err("QUOTA_EXCEEDED", "cache policy invalid (max_entry_bytes)"), "error", "QUOTA_EXCEEDED")
            if value_bytes > max_entry_bytes:
                return _finalize_and_return(_err("QUOTA_EXCEEDED", "entry exceeds max_entry_bytes", max_entry_bytes=max_entry_bytes, value_bytes=value_bytes), "error", "QUOTA_EXCEEDED")

        # Derive current active counts/bytes
        def _is_active_row(r):
            return r.get("status") == "active"

        active_rows = [r for r in entries if _is_active_row(r)]
        active_keys = len(active_rows)
        approx_bytes = sum(int(r.get("value_bytes") or 0) for r in active_rows)

        existing_non_deleted = None
        for r in entries:
            if r.get("cache_key") == key and r.get("status") != "deleted":
                existing_non_deleted = r
                break

        projected_active_keys = active_keys
        projected_approx_bytes = approx_bytes

        if existing_non_deleted is None:
            projected_active_keys = active_keys + 1
            projected_approx_bytes = approx_bytes + value_bytes
        else:
            # If overwriting an expired row, it becomes active; if overwriting active, active_keys unchanged
            old_status = existing_non_deleted.get("status")
            old_bytes = int(existing_non_deleted.get("value_bytes") or 0)
            if old_status == "active":
                projected_approx_bytes = approx_bytes - old_bytes + value_bytes
            elif old_status == "expired":
                projected_active_keys = active_keys + 1
                projected_approx_bytes = approx_bytes + value_bytes
            else:
                # shouldn't happen because non-deleted
                projected_active_keys = active_keys + 1
                projected_approx_bytes = approx_bytes + value_bytes

        if max_keys is not None:
            if not isinstance(max_keys, int) or max_keys <= 0:
                return _finalize_and_return(_err("QUOTA_EXCEEDED", "cache policy invalid (max_keys)"), "error", "QUOTA_EXCEEDED")
            if projected_active_keys > max_keys:
                return _finalize_and_return(_err("QUOTA_EXCEEDED", "active key limit exceeded", max_keys=max_keys, projected_active_keys=projected_active_keys), "error", "QUOTA_EXCEEDED")

        if max_total_bytes is not None:
            if not isinstance(max_total_bytes, int) or max_total_bytes <= 0:
                return _finalize_and_return(_err("QUOTA_EXCEEDED", "cache policy invalid (max_total_bytes)"), "error", "QUOTA_EXCEEDED")
            if projected_approx_bytes > max_total_bytes:
                return _finalize_and_return(_err("QUOTA_EXCEEDED", "total bytes limit exceeded", max_total_bytes=max_total_bytes, projected_approx_bytes=projected_approx_bytes), "error", "QUOTA_EXCEEDED")

    # Upsert/overwrite logic: unique(cache_key) where status != 'deleted'
    existing = None
    for r in entries:
        if r.get("cache_key") == key and r.get("status") != "deleted":
            existing = r
            break

    if ttl is None:
        ttl_seconds = None
        expires_at = None
    else:
        ttl_seconds = float(ttl)
        exp = now + datetime.timedelta(seconds=ttl_seconds)
        expires_at = exp.replace(microsecond=0).isoformat() + "Z"

    if existing is None:
        entry_id = "ce_" + uuid.uuid4().hex
        new_row = {
            "id": entry_id,
            "cache_key": key,
            "value_json": value,
            "value_bytes": int(value_bytes),
            "ttl_seconds": ttl_seconds,
            "expires_at": expires_at,
            "last_accessed_at": None,
            "write_count": 1,
            "read_count": 0,
            "status": "active",
            "deleted_at": None,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        entries.append(new_row)
        op_row["cache_entry_id"] = entry_id
        _save("cache_entries.json", entries)
        return _finalize_and_return(
            {"key": key, "ttl": ttl_seconds, "status": "active"},
            "success",
            None,
        )

    # Overwrite existing non-deleted entry
    # Transition to active always allowed from active/expired
    if existing.get("status") == "deleted":
        # should not happen given selection
        return _finalize_and_return(_err("CONFLICT", "cannot overwrite deleted entry"), "error", "CONFLICT")

    existing["value_json"] = value
    existing["value_bytes"] = int(value_bytes)
    existing["ttl_seconds"] = ttl_seconds
    existing["expires_at"] = expires_at
    existing["write_count"] = int(existing.get("write_count") or 0) + 1
    existing["status"] = "active"
    existing["deleted_at"] = None
    existing["updated_at"] = now_iso
    op_row["cache_entry_id"] = existing.get("id")
    _save("cache_entries.json", entries)

    return _finalize_and_return(
        {"key": key, "ttl": ttl_seconds, "status": "active"},
        "success",
        None,
    )

def retrieve_data(key, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0180000" if __import__("os").path.isdir("./environment_mix/0180000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0)
    now_iso = now.isoformat() + "Z"

    entries = _load("cache_entries.json")
    ops = _load("cache_operations.json")

    op_row = {
        "id": "op_" + uuid.uuid4().hex,
        "op_type": "retrieve_data",
        "cache_entry_id": None,
        "cache_key": key if isinstance(key, str) else None,
        "ttl_seconds": None,
        "result": "error",
        "error_code": None,
        "duration_ms": None,
        "created_at": now_iso,
        "updated_at": now_iso,
    }

    def _finalize(payload, result, error_code=None):
        op_row["result"] = result
        op_row["error_code"] = error_code
        op_row["duration_ms"] = max(0, int(round((time.time() - t0) * 1000)))
        op_row["updated_at"] = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
        ops.append(op_row)
        _save("cache_operations.json", ops)
        return payload

    if not isinstance(key, str) or key.strip() == "":
        return _finalize(_err("VALIDATION_ERROR", "key must be a non-empty string"), "error", "VALIDATION_ERROR")

    # find non-deleted entry
    entry = None
    for r in entries:
        if r.get("cache_key") == key and r.get("status") != "deleted":
            entry = r
            break

    if entry is None:
        # miss
        return _finalize(_err("NOT_FOUND", "cache miss"), "miss", None)

    op_row["cache_entry_id"] = entry.get("id")

    # Check expiration
    expires_at = entry.get("expires_at")
    if expires_at is not None:
        try:
            exp = datetime.datetime.fromisoformat(expires_at.replace("Z", ""))
        except ValueError:
            # Bad stored data, treat as error
            return _finalize(_err("CONFLICT", "stored expires_at is invalid"), "error", "CONFLICT")
        if now >= exp:
            # lazily mark expired if currently active
            if entry.get("status") == "active":
                # active -> expired transition allowed
                entry["status"] = "expired"
                entry["updated_at"] = now_iso
                _save("cache_entries.json", entries)
            # return expired as NOT_FOUND per tool description
            return _finalize(_err("NOT_FOUND", "cache entry expired"), "expired", None)

    # If entry is expired already (but expires_at in future? or null with status expired), treat as unavailable
    if entry.get("status") == "expired":
        return _finalize(_err("NOT_FOUND", "cache entry expired"), "expired", None)

    # active hit
    entry["last_accessed_at"] = now_iso
    entry["read_count"] = int(entry.get("read_count") or 0) + 1
    entry["updated_at"] = now_iso
    _save("cache_entries.json", entries)

    return _finalize(
        {"key": key, "value": entry.get("value_json"), "status": entry.get("status")},
        "success",
        None,
    )

def list_cache_entries(status=None, key_prefix=None, include_value=None, page_size=None, page_token=None, **_extra):
    import json, os, datetime, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0180000" if __import__("os").path.isdir("./environment_mix/0180000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)

    # --- helpers
    def _iso(dt):
        if dt is None:
            return None
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.isoformat().replace("+00:00", "Z")
        return dt

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s.strip():
            return None
        ss = s.strip()
        if ss.endswith("Z"):
            ss = ss[:-1] + "+00:00"
        return datetime.datetime.fromisoformat(ss)

    def _duration_ms():
        return int(max(0, round((time.time() - t0) * 1000)))

    def _new_id(prefix):
        import secrets
        return f"{prefix}_{secrets.token_hex(12)}"

    def _log(op_type, result, cache_entry_id=None, cache_key=None, ttl_seconds=None, error_code=None):
        ops = _load("cache_operations.json")
        row = {
            "id": _new_id("op"),
            "op_type": op_type,
            "cache_entry_id": cache_entry_id,
            "cache_key": cache_key,
            "ttl_seconds": ttl_seconds,
            "result": result,
            "error_code": error_code,
            "duration_ms": None,  # set just before save/return
            "created_at": _iso(now),
            "updated_at": _iso(now),
        }
        ops.append(row)
        _save("cache_operations.json", ops)
        return row["id"]

    def _policy_active():
        pols = _load("cache_retention_policies.json")
        act = [p for p in pols if isinstance(p, dict) and p.get("status") == "active"]
        if len(act) == 1:
            return act[0]
        if len(act) == 0:
            return None
        # data invalid: treat as conflict for operations that rely on policy; here, reads only.
        return act[0]

    def _decode_token(tok):
        if tok is None:
            return None
        if not isinstance(tok, str) or not tok:
            return None
        try:
            raw = base64.urlsafe_b64decode(tok.encode("utf-8") + b"===")
            obj = json.loads(raw.decode("utf-8"))
            if not isinstance(obj, dict):
                return None
            return obj
        except Exception:
            return None

    def _encode_token(obj):
        raw = json.dumps(obj, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    # --- validation
    if status is not None:
        if not isinstance(status, str) or status not in ("active", "expired", "deleted"):
            op_id = _log("get_cache_stats", "error", error_code="VALIDATION_ERROR")
            ops = _load("cache_operations.json")
            for r in reversed(ops):
                if r.get("id") == op_id:
                    r["duration_ms"] = _duration_ms()
                    r["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
                    break
            _save("cache_operations.json", ops)
            return _err("VALIDATION_ERROR", "Invalid status filter.", allowed=["active", "expired", "deleted"])
    if key_prefix is not None and not isinstance(key_prefix, str):
        op_id = _log("get_cache_stats", "error", error_code="VALIDATION_ERROR")
        ops = _load("cache_operations.json")
        for r in reversed(ops):
            if r.get("id") == op_id:
                r["duration_ms"] = _duration_ms()
                r["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
                break
        _save("cache_operations.json", ops)
        return _err("VALIDATION_ERROR", "key_prefix must be a string.")
    if include_value is None:
        include_value = False
    if not isinstance(include_value, bool):
        op_id = _log("get_cache_stats", "error", error_code="VALIDATION_ERROR")
        ops = _load("cache_operations.json")
        for r in reversed(ops):
            if r.get("id") == op_id:
                r["duration_ms"] = _duration_ms()
                r["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
                break
        _save("cache_operations.json", ops)
        return _err("VALIDATION_ERROR", "include_value must be a boolean.")
    if page_size is None:
        page_size = 50
    if not isinstance(page_size, int) or page_size < 1 or page_size > 200:
        op_id = _log("get_cache_stats", "error", error_code="VALIDATION_ERROR")
        ops = _load("cache_operations.json")
        for r in reversed(ops):
            if r.get("id") == op_id:
                r["duration_ms"] = _duration_ms()
                r["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
                break
        _save("cache_operations.json", ops)
        return _err("VALIDATION_ERROR", "page_size must be an integer between 1 and 200.")

    token = None
    if page_token is not None:
        if not isinstance(page_token, str) or not page_token:
            op_id = _log("get_cache_stats", "error", error_code="VALIDATION_ERROR")
            ops = _load("cache_operations.json")
            for r in reversed(ops):
                if r.get("id") == op_id:
                    r["duration_ms"] = _duration_ms()
                    r["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
                    break
            _save("cache_operations.json", ops)
            return _err("VALIDATION_ERROR", "page_token must be a non-empty string.")
        token = _decode_token(page_token)
        if token is None or token.get("v") != 1 or token.get("t") != "entries":
            op_id = _log("get_cache_stats", "error", error_code="VALIDATION_ERROR")
            ops = _load("cache_operations.json")
            for r in reversed(ops):
                if r.get("id") == op_id:
                    r["duration_ms"] = _duration_ms()
                    r["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
                    break
            _save("cache_operations.json", ops)
            return _err("VALIDATION_ERROR", "Invalid page_token.")

        # enforce same filters across pages
        if token.get("status") != status or token.get("key_prefix") != key_prefix or bool(token.get("include_value")) != bool(include_value):
            op_id = _log("get_cache_stats", "error", error_code="VALIDATION_ERROR")
            ops = _load("cache_operations.json")
            for r in reversed(ops):
                if r.get("id") == op_id:
                    r["duration_ms"] = _duration_ms()
                    r["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
                    break
            _save("cache_operations.json", ops)
            return _err("VALIDATION_ERROR", "page_token does not match current filters.")

    # --- "authorization": ambient; refuse only if store cannot support reading at all
    # If datastore missing collections entirely, treat as unauthorized only if absolutely nothing exists.
    entries = _load("cache_entries.json")
    ops = _load("cache_operations.json")
    pol = _policy_active()  # load to ensure schema presence; not used for auth
    if entries == [] and ops == [] and _load("cache_stats_snapshots.json") == [] and _load("cache_retention_policies.json") == []:
        op_id = _log("get_cache_stats", "error", error_code="UNAUTHORIZED")
        ops2 = _load("cache_operations.json")
        for r in reversed(ops2):
            if r.get("id") == op_id:
                r["duration_ms"] = _duration_ms()
                r["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
                break
        _save("cache_operations.json", ops2)
        return _err("UNAUTHORIZED", "Caller is not authorized to read cache metadata.")

    # --- filter
    def _matches(e):
        if not isinstance(e, dict):
            return False
        if status is not None and e.get("status") != status:
            return False
        if key_prefix is not None:
            ck = e.get("cache_key")
            if not isinstance(ck, str) or not ck.startswith(key_prefix):
                return False
        return True

    filtered = [e for e in entries if _matches(e)]

    # order by updated_at desc, then id desc for stability
    def _sort_key(e):
        dt = None
        try:
            dt = _parse_dt(e.get("updated_at"))
        except Exception:
            dt = None
        # None sorts oldest
        ts = dt.timestamp() if isinstance(dt, datetime.datetime) else float("-inf")
        return (ts, e.get("id") or "")

    filtered.sort(key=_sort_key, reverse=True)

    start = 0
    if token is not None:
        try:
            start = int(token.get("offset", 0))
            if start < 0:
                raise ValueError()
        except Exception:
            op_id = _log("get_cache_stats", "error", error_code="VALIDATION_ERROR")
            ops2 = _load("cache_operations.json")
            for r in reversed(ops2):
                if r.get("id") == op_id:
                    r["duration_ms"] = _duration_ms()
                    r["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
                    break
            _save("cache_operations.json", ops2)
            return _err("VALIDATION_ERROR", "Invalid page_token offset.")

    total = len(filtered)
    page = filtered[start:start + page_size]
    next_offset = start + len(page)
    has_more = next_offset < total
    next_token = None
    if has_more:
        next_token = _encode_token({"v": 1, "t": "entries", "offset": next_offset, "status": status, "key_prefix": key_prefix, "include_value": include_value})

    # shape response items
    items = []
    for e in page:
        item = {
            "id": e.get("id"),
            "cache_key": e.get("cache_key"),
            "ttl_seconds": e.get("ttl_seconds"),
            "expires_at": e.get("expires_at"),
            "last_accessed_at": e.get("last_accessed_at"),
            "write_count": e.get("write_count"),
            "read_count": e.get("read_count"),
            "status": e.get("status"),
            "deleted_at": e.get("deleted_at"),
            "created_at": e.get("created_at"),
            "updated_at": e.get("updated_at"),
        }
        if include_value:
            item["value_json"] = e.get("value_json")
            item["value_bytes"] = e.get("value_bytes")
        items.append(item)

    # log call as an operation (reads included). Use get_cache_stats op_type as closest available.
    op_id = _log("get_cache_stats", "success")
    ops2 = _load("cache_operations.json")
    for r in reversed(ops2):
        if r.get("id") == op_id:
            r["duration_ms"] = _duration_ms()
            r["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
            break
    _save("cache_operations.json", ops2)

    return {
        "items": items,
        "page_size": page_size,
        "next_page_token": next_token,
        "has_more": has_more,
        "total": total,
    }

def get_cache_entry(id, include_value=None, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0180000" if __import__("os").path.isdir("./environment_mix/0180000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if dt is None:
            return None
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.isoformat().replace("+00:00", "Z")
        return dt

    def _duration_ms():
        return int(max(0, round((time.time() - t0) * 1000)))

    def _new_id(prefix):
