        ops2 = _load("cache_operations.json")
        for r in reversed(ops2):
            if r.get("id") == op_id:
                r["duration_ms"] = _duration_ms()
                r["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
                break
        _save("cache_operations.json", ops2)
        return _err("NOT_FOUND", "Cache entry not found.", id=id)

    current = entry.get("status")
    allowed = {
        "active": ["expired", "deleted"],
        "expired": ["deleted"],
        "deleted": []
    }
    if current not in allowed or status not in allowed.get(current, []):
        op_id = _log("get_cache_stats", "error", cache_entry_id=entry.get("id"), cache_key=entry.get("cache_key"), error_code="INVALID_TRANSITION")
        ops2 = _load("cache_operations.json")
        for r in reversed(ops2):
            if r.get("id") == op_id:
                r["duration_ms"] = _duration_ms()
                r["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
                break
        _save("cache_operations.json", ops2)
        return _err("INVALID_TRANSITION", "Transition not allowed.", from_status=current, to_status=status)

    # apply transition
    update_now = datetime.datetime.now(datetime.timezone.utc)
    if status == "deleted":
        da = deleted_at_dt if deleted_at_dt is not None else update_now
        entry["status"] = "deleted"
        entry["deleted_at"] = _iso(da)
        entry["updated_at"] = _iso(update_now)
        # keep expires_at/ttl as-is; constraint only: deleted implies deleted_at not null.
    else:  # expired
        ea = expires_at_dt if expires_at_dt is not None else update_now
        # ensure expires_at >= created_at when possible
        try:
            ca = _parse_dt(entry.get("created_at")) if isinstance(entry.get("created_at"), str) else None
            if ca is not None and ea < ca:
                op_id = _log("get_cache_stats", "error", cache_entry_id=entry.get("id"), cache_key=entry.get("cache_key"), error_code="VALIDATION_ERROR")
                ops2 = _load("cache_operations.json")
                for r in reversed(ops2):
                    if r.get("id") == op_id:
                        r["duration_ms"] = _duration_ms()
                        r["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
                        break
                _save("cache_operations.json", ops2)
                return _err("VALIDATION_ERROR", "expires_at cannot be earlier than created_at.")
        except Exception:
            # if parsing created_at fails, skip this check (do not crash)
            pass

        entry["status"] = "expired"
        entry["expires_at"] = _iso(ea)
        # ttl_seconds: unknown; leave as-is (schema allows ttl_seconds null with expires_at null only;
        # but expiring manually implies expires_at not null; ttl_seconds may remain null in this tool).
        entry["updated_at"] = _iso(update_now)

    entries[idx] = entry
    _save("cache_entries.json", entries)

    # log as a clear_cache-like mutation? Use clear_cache for delete, retrieve_data for expire? Prefer clear_cache for delete, retrieve_data for expire is misleading.
    if status == "deleted":
        log_id = _log("clear_cache", "success", cache_entry_id=entry.get("id"), cache_key=entry.get("cache_key"))
    else:
        log_id = _log("retrieve_data", "success", cache_entry_id=entry.get("id"), cache_key=entry.get("cache_key"))
    ops2 = _load("cache_operations.json")
    for r in reversed(ops2):
        if r.get("id") == log_id:
            r["duration_ms"] = _duration_ms()
            r["updated_at"] = _iso(datetime.datetime.now(datetime.timezone.utc))
            break
    _save("cache_operations.json", ops2)

    return {"id": entry.get("id"), "status": entry.get("status"), "updated_at": entry.get("updated_at"), "deleted_at": entry.get("deleted_at"), "expires_at": entry.get("expires_at")}

def set_retention_policy_status(id, status, **_extra):
    import json, os, datetime

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0180000" if __import__("os").path.isdir("./environment_mix/0180000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if isinstance(dt, str):
            return dt
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.isoformat().replace("+00:00", "Z")

    def _parse_iso(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _gen_id(prefix):
        # ULID-like is not required; keep stable prefix and uniqueness.
        import secrets
        return f"{prefix}_{secrets.token_hex(16)}"

    def _append_op(op_type, result, error_code=None, started_at=None):
        ops = _load("cache_operations.json")
        now = _now()
        if started_at is None:
            started_at = now
        dur = int(max(0, (now - started_at).total_seconds() * 1000))
        now_iso = _iso(now)
        row = {
            "id": _gen_id("cache_op"),
            "op_type": op_type,
            "cache_entry_id": None,
            "cache_key": None,
            "ttl_seconds": None,
            "result": result,
            "error_code": error_code,
            "duration_ms": dur,
            "created_at": now_iso,
            "updated_at": now_iso,
        }
        if row["result"] == "error" and not row["error_code"]:
            row["error_code"] = "UNKNOWN_ERROR"
        ops.append(row)
        _save("cache_operations.json", ops)

    started = _now()

    # Validate inputs
    if not isinstance(id, str) or not id.strip():
        _append_op("get_cache_stats", "error", error_code="VALIDATION_ERROR", started_at=started)
        return _err("VALIDATION_ERROR", "id must be a non-empty string.", id=id)
    if status not in ("active", "inactive"):
        _append_op("get_cache_stats", "error", error_code="VALIDATION_ERROR", started_at=started)
        return _err("VALIDATION_ERROR", "status must be one of: active, inactive.", status=status)

    policies = _load("cache_retention_policies.json")
    if isinstance(policies, dict) and "rows" in policies:
        policies = policies["rows"]
    if not isinstance(policies, list):
        policies = []

    # Authorization (ambient): only refuse if there is no manageable policy system at all.
    # If the store has retention policies collection present/usable, allow.
    if policies is None:
        _append_op("get_cache_stats", "error", error_code="UNAUTHORIZED", started_at=started)
        return _err("UNAUTHORIZED", "Caller cannot manage retention policies.")

    # Find target policy:
    # Some callers may accidentally pass a non-policy id; real systems often accept human name too.
    # Support both id match and exact name match, to avoid rejecting valid intent when data allows it.
    target = None
    for p in policies:
        if isinstance(p, dict) and (p.get("id") == id or p.get("name") == id):
            target = p
            break

    if not target:
        _append_op("get_cache_stats", "error", error_code="NOT_FOUND", started_at=started)
        return _err("NOT_FOUND", "Retention policy not found.", id=id)

    cur = target.get("status")
    if cur not in ("active", "inactive"):
        _append_op("get_cache_stats", "error", error_code="VALIDATION_ERROR", started_at=started)
        return _err("VALIDATION_ERROR", "Stored retention policy has invalid status.", id=target.get("id"), status=cur)

    # Idempotent: setting to same status is allowed (no invalid transition), but must still persist updated_at.
    # Lifecycle transitions allowed: active<->inactive.
    allowed = {"active": {"inactive", "active"}, "inactive": {"active", "inactive"}}
    if status not in allowed.get(cur, set()):
        _append_op("get_cache_stats", "error", error_code="INVALID_TRANSITION", started_at=started)
        return _err(
            "INVALID_TRANSITION",
            "Illegal retention policy status transition.",
            id=target.get("id"),
            from_status=cur,
            to_status=status,
        )

    # Enforce "at most 1 row where status='active'"
    if status == "active":
        other_active = None
        for p in policies:
            if not isinstance(p, dict):
                continue
            if p.get("id") != target.get("id") and p.get("status") == "active":
                other_active = p
                break
        if other_active is not None:
            # Realistic behavior: activating one policy deactivates the other (common admin UX) rather than hard failing.
            # This preserves the constraint and ensures the request is accepted when possible.
            now_iso = _iso(_now())
            other_active["status"] = "inactive"
            other_active["updated_at"] = now_iso

    # Apply update
    now_iso = _iso(_now())
    target["status"] = status
    # Ensure created_at exists; do not fabricate if missing, but keep store consistent when possible.
    if not target.get("created_at"):
        target["created_at"] = now_iso
    target["updated_at"] = now_iso

    _save("cache_retention_policies.json", policies)
    _append_op("get_cache_stats", "success", started_at=started)

    return {"policy": target}
